import{_ as t,o,c as a,aa as s}from"./chunks/framework.oWfRcsIL.js";const u=JSON.parse('{"title":"Scope","description":"How in-scope hosts, out-of-scope hosts and seed URLs define what syslifters.ai agents may touch.","frontmatter":{"title":"Scope","description":"How in-scope hosts, out-of-scope hosts and seed URLs define what syslifters.ai agents may touch."},"headers":[],"relativePath":"legal/scope.md","filePath":"legal/scope.md"}'),n={name:"legal/scope.md"};function r(i,e,c,d,h,l){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h1><p>The scope defines which systems the agents are allowed to send traffic to. It is enforced technically: every request from an agent passes through a proxy and a firewall that only let in-scope traffic through. An agent cannot reach an out-of-scope host, even if it tries.</p><p>You set the scope in three fields when you create a project:</p><table tabindex="0"><thead><tr><th>Field</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>In-scope hosts / URLs</strong></td><td>Everything the agents are allowed to touch.</td></tr><tr><td><strong>Out-of-scope hosts / URLs</strong></td><td>Exceptions. They always win over in-scope entries.</td></tr><tr><td><strong>Seed URLs</strong></td><td>Entry points where recon starts. They are in scope automatically.</td></tr></tbody></table><p>Write one entry per line in each field.</p><h2 id="in-scope-entries" tabindex="-1">In-scope entries <a class="header-anchor" href="#in-scope-entries" aria-label="Permalink to &quot;In-scope entries&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You write</th><th>What is in scope</th></tr></thead><tbody><tr><td><code>app.example.com</code></td><td>The whole host, on every port.</td></tr><tr><td><code>app.example.com:8443</code></td><td>Only that one service: the host on port 8443.</td></tr><tr><td><code>https://app.example.com</code></td><td>The host on port 443 (the default port of the scheme).</td></tr><tr><td><code>http://app.example.com:8080/</code></td><td>The host on port 8080.</td></tr><tr><td><code>*.example.com</code></td><td>Every subdomain of <code>example.com</code>, on every port. It does <strong>not</strong> include <code>example.com</code> itself; add that as a separate line.</td></tr><tr><td><code>203.0.113.10</code></td><td>That IP address, on every port.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Scope is per host and port, not per path</p><p>A URL path does not limit the scope. <code>https://app.example.com/shop</code> puts <strong>all</strong> of <code>app.example.com</code> on port 443 into scope, including <code>/admin</code>. If parts of a host must not be tested, the host cannot be split by path; agree with the system owner that the whole host may be tested, or leave it out.</p></div><h2 id="out-of-scope-entries" tabindex="-1">Out-of-scope entries <a class="header-anchor" href="#out-of-scope-entries" aria-label="Permalink to &quot;Out-of-scope entries&quot;">​</a></h2><p>Out-of-scope entries always beat in-scope entries (&quot;deny wins&quot;). Use them to cut exceptions out of a wider scope.</p><table tabindex="0"><thead><tr><th>You write</th><th>What is excluded</th></tr></thead><tbody><tr><td><code>payments.example.com</code></td><td>The whole host, on every port, even if <code>*.example.com</code> is in scope.</td></tr><tr><td><code>app.example.com:9000</code></td><td>Only port 9000 of that host.</td></tr><tr><td><code>https://sso.example.com</code></td><td>The <strong>whole</strong> host. A URL without an explicit port excludes all ports, not only 443.</td></tr></tbody></table><p>Typical exclusions are third-party services that the application uses but that you have no permission to test: payment providers, single sign-on providers, CDNs, analytics, chat widgets and email services. The agents may still see those services referenced in the application, but they cannot send traffic to them.</p><h2 id="seed-urls" tabindex="-1">Seed URLs <a class="header-anchor" href="#seed-urls" aria-label="Permalink to &quot;Seed URLs&quot;">​</a></h2><p>Seed URLs are where recon starts. Surface mapping, crawling and attack planning all begin from them, and their hosts are automatically in scope.</p><ul><li>For web app and API projects at least one seed URL is required. Without seed URLs, recon does not run and the hunting agents work without a map of the application.</li><li>List the entry points completely: the login page, the main application, the API base URL, an admin area, documentation such as an OpenAPI file. A part of the application that recon never reaches is never tested.</li><li>For mobile-only projects the uploaded app (<code>.apk</code>) is the entry point, and seed URLs are optional.</li></ul><h2 id="changing-scope-during-a-run" tabindex="-1">Changing scope during a run <a class="header-anchor" href="#changing-scope-during-a-run" aria-label="Permalink to &quot;Changing scope during a run&quot;">​</a></h2><p>There are two ways the scope changes after a project was created. In both cases you are responsible for having <a href="/legal/authorization">permission</a> for the new host.</p><h3 id="edit-scope" tabindex="-1">Edit scope <a class="header-anchor" href="#edit-scope" aria-label="Permalink to &quot;Edit scope&quot;">​</a></h3><p>On the <strong>Overview</strong> tab, <strong>Edit scope</strong> lets you change the in-scope and out-of-scope lists at any time.</p><ul><li>The change applies immediately to agents that are already running, both additions and removals. A removed host loses access within seconds.</li><li>Agents are told about the change the next time they continue: a new host is reported as reachable, a removed host as off limits.</li><li>If hosts are added while the project is hunting, the already tested categories are reopened so the new host gets tested too. A paused or finished project needs <strong>Resume</strong> for that.</li></ul><h3 id="approving-an-agent-s-request" tabindex="-1">Approving an agent&#39;s request <a class="header-anchor" href="#approving-an-agent-s-request" aria-label="Permalink to &quot;Approving an agent&#39;s request&quot;">​</a></h3><p>When an agent needs a host that is not in scope (for example an API on another subdomain it discovered), it asks you through an approval request. <strong>Allow &amp; add host</strong> adds the host to the scope permanently for the whole project. <strong>Allow once</strong> only allows that single action. <strong>Deny</strong> blocks it. See <a href="/getting-started/safety-controls#approvals">Safety controls</a>.</p><h2 id="checklist" tabindex="-1">Checklist <a class="header-anchor" href="#checklist" aria-label="Permalink to &quot;Checklist&quot;">​</a></h2><ul class="contains-task-list"><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> Every in-scope entry is covered by my authorization, including all ports and paths of each host.</li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> Third-party services (payment, SSO, CDN, analytics) are listed as out of scope.</li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> Seed URLs cover every entry point of the application.</li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> Wildcards (<code>*.example.com</code>) only cover subdomains I am allowed to test.</li></ul>',24)])])}const m=t(n,[["render",r]]);export{u as __pageData,m as default};
